"""Experimental: whole handwritten text lines generated by DiffBrush (ICCV 2025).

A v2 prototype that sits beside the SDT pipeline and changes nothing in it.
DiffBrush writes a full line as an image, imitating one reference line; the
released checkpoint only knows English (IAM letters).

Optional: ``pip install -e ".[linegen]"`` (torch, torchvision, diffusers, einops).
Nothing outside this package imports torch or diffusers at module level.

- :mod:`.weights`: download and cache the checkpoint, SD1.5 VAE and glyphs (no torch).
- :mod:`.style`: reference line loading, text checks, wrapping (no torch).
- :mod:`.device`: CUDA / ROCm / DirectML / CPU selection.
- :mod:`.generate`: :class:`~.generate.LineGenerator` and :func:`~.generate.generate_lines`.
- :mod:`.bench`: speed on this machine plus FLOP-based estimates for other cards.
- :mod:`.net`: the network, vendored from DiffBrush (MIT).
"""

from __future__ import annotations


def available() -> bool:
    """Whether the optional linegen dependencies are installed."""
    try:
        import diffusers  # noqa: F401
        import einops  # noqa: F401
        import torch  # noqa: F401
        import torchvision  # noqa: F401
    except ImportError:
        return False
    return True
